<!--vbase-->
<template>
  <div class="row q-pl-xl q-pr-md q-pb-md full-width">
    <div class="max-width-100" id="left_section" ref="left_section">
      <div class="full-width q-ma-sm scroll-area-height">
        <div class="row justify-center q-pl-md q-pr-md q-pt-md">
          <span class="secondary-c-text text-h6 text-weight-bold">
            {{ $t('page_number_text') }}
          </span>
        </div>

        <div class="full-width left-scroll-area-height scrolle-y q-pa-sm">
          <img
            v-for="(imageMoc, index) in images"
            :data-id="index"
            :key="index"
            :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
            class="q-pa-xs shadow-5 full-width q-ma-sm cursor-pointer"
            :class="index === (page_number as any) - 1 ? 'active' : ''"
            style="height: auto"
            @click="imageclicked(String(index))"
          />
        </div>
      </div>
    </div>

    <div class="right_section" id="right_section" ref="right_section">
      <div class="row full-height">
        <div
          class="col-xs-12 col-sm-12 col-md-12 col-lg-12 q-px-sm scroll-area-height"
        >
          <div class="mb-4 image_control_panel">
            <div class="row full-height">
              <div class="panel-left col-sm-6 col-md-6 col-lg-6">
                <div class="row">
                  <q-btn
                    id="menu_btn"
                    round
                    icon="chevron_left"
                    size="xs"
                    class="toggler-right p-t-40"
                    @click="toggleMenu()"
                  />
                  {{ filename }}
                </div>
              </div>
              <div class="panel-middle col-sm-1 col-md-1 col-lg-1 mt-8">
                <span class="page-numbers"
                  >{{ currentPage() }}/{{ images.length }}</span
                >
              </div>
              <div class="panel-right col-sm-5 col-md-5 col-lg-5">
                <q-btn
                  flat
                  v-if="doc_mode.includes(mode)"
                  @click="mode = 'doc'"
                  class="float-right pr-6 pl-6"
                >
                  <Icon icon="mdi:file-eye" width="24" height="24" />
                  <q-tooltip>{{ $t('doc_view') }}</q-tooltip>
                </q-btn>

                <q-btn
                  flat
                  v-if="ocr_mode.includes(mode)"
                  @click="mode = 'ocr'"
                  class="float-right pr-6 pl-6"
                >
                  <Icon icon="mdi:text-recognition" width="24" height="24" />
                  <q-tooltip>{{ $t('ocr_view') }}</q-tooltip>
                </q-btn>

                <q-btn
                  flat
                  v-if="debug_on_mode.includes(mode)"
                  @click="mode = 'debug_on'"
                  class="float-right pr-6 pl-6"
                >
                  <Icon icon="mdi:bug" width="24" height="24" />
                  <q-tooltip>{{ $t('debug_view') }}</q-tooltip>
                </q-btn>

                <span class="float-right table-mode mode-on">
                  <template v-if="mode == 'doc'">
                    {{ $t('doc_view') }} : ON
                  </template>
                  <template v-if="mode == 'ocr'">
                    {{ $t('ocr_view') }} : ON
                  </template>
                  <template v-if="mode == 'debug_on'">
                    {{ $t('debug_view') }} : ON
                  </template>
                </span>
              </div>
            </div>
          </div>
          <div class="full-width full-height" id="image_container">
            <div
              class="full-width full-height q-pa-sm scrolle-y"
              id="image_scrolle"
              style="position: relative"
            >
              <OcrTokenAreas
                :pos-correction="false"
                :width="imageWidth"
                :tableAreas="tokens"
                :height="imageHeight"
                :cropUrl="image + '?' + tokenQueryParam"
                :mode="mode"
                :token_len="tokens.length"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { useImageAuth } from 'src/composables/useImageAuth';
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { defineComponent, ref, computed } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import {
  useDocumentStore,
  useDropdownStore} from 'src/store/main';
import {
  getOcrDataInSession,
  addOcrDataInExistingSession,
  getDocDataName,
  removeOcrData,
  getOcrSessionName,
} from 'src/utils/ocr_doc';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import OcrTokenAreas from 'src/pages/OcrDocument/OcrTokenAreas.vue';
import { isObjectEmtpy } from 'src/utils/general';
import Loader from 'src/components/Loader.vue';
import { LocalStorage } from 'quasar';
import { useTolgee } from '@tolgee/vue';
import { getOrgId } from 'src/utils/organization/org_id_helper';

const $ = document.querySelector.bind(document);
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    OcrTokenAreas,
    Loader,
    
  },
  data() {
    return {
      docId: '',
      doc_data_name: '',
      imageHeight: 0,
      imageWidth: 0,
      filename: '',
      ocr_mode: ['doc', 'debug_on'],
      doc_mode: ['ocr', 'debug_on'],
      debug_on_mode: ['ocr', 'doc'],
    };
  },
  setup() {
    const tolgee = useTolgee(['language']);
    const locale = computed(() => tolgee.value.getLanguage() || 'en');
    let model = {} as { [k: string]: any };
    let data: any = [];

    const doc_store = useDocumentStore();
    const { getDocumentById } = doc_store;
    const { record } = storeToRefs(doc_store);

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    const dropdownStore = useDropdownStore();
    const { getSelectedLanguage } = dropdownStore;

    return {
      getDocumentById,
      getSelectedLanguage,
      record,
      locale,
      apiData: ref(model),
      page_number: ref(''),
      images: ref(data),
      baseUrl: DOC2API_URL,
      image: ref(''),
      tokens: ref(data),
      alert_counts: ref(data),
      mode: ref('ocr'),
      tokenQueryParam,
    };
  },
  mounted() {
    this.getSelectedLanguage();

    this.docId = this.$route.params.id as string;
    this.page_number = this.$route.params.page_number as string;
    this.init();
  },
  methods: {
    async init() {
      try {
        this.showLoading();
        removeOcrData(getOcrSessionName(this.docId));
        this.doc_data_name = getDocDataName();

        let get_ocr_data = false;
        let cached_api_data = getOcrDataInSession(this.docId);
        if (cached_api_data !== null) {
          this.updateLocalData(cached_api_data);
        }

        if (!this.isPageNumberOcrDataExist(this.page_number)) {
          get_ocr_data = true;
        }

        if (get_ocr_data) {
          await this.getDocumentOcrData();
        }

        if (
          !this.apiData ||
          !this.apiData.hasOwnProperty(this.doc_data_name) ||
          !this.apiData[this.doc_data_name].hasOwnProperty('images')
        ) {
          await this.getInvoiceDataByDocId();
        }

        this.setImages();
        this.filename =
          this.apiData[this.doc_data_name] &&
          this.apiData[this.doc_data_name].filename
            ? this.apiData[this.doc_data_name].filename
            : '';
        this.renderView();
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
        this.hideLoading();
      } finally {
      }
    },

    updateLocalData(data: any, attribute_name = '-1') {
      if (attribute_name !== '-1') {
        this.apiData[attribute_name] = data;
        addOcrDataInExistingSession(data, attribute_name, this.docId);
        return;
      }

      this.apiData = data;
    },
    isPageNumberOcrDataExist(page_number = '0') {
      if (
        page_number === '0' ||
        isObjectEmtpy(this.apiData) ||
        !this.apiData.hasOwnProperty(page_number) ||
        isObjectEmtpy(this.apiData[page_number]) ||
        !this.apiData[page_number].hasOwnProperty('tokens') ||
        !Array.isArray(this.apiData[page_number].tokens)
      ) {
        return false;
      }
      return true;
    },
    async getDocumentOcrData() {
      if (!this.page_number) {
        throw { message: 'Page Number is missing' };
      }

      let response: any;
      this.page_number = this.page_number.toString();
      let formData = new FormData();
      formData.append('page_number', this.page_number);
      formData.append('include_font_size', true.toString());
      formData.append('org_id', getOrgId());
      let token: string = await getAuthorizationToken();
      response = await axios.post(api.get_ocr_data + this.docId, formData, {
        headers: {
          Authorization: token,
        },
      });

      if (response.data.success !== true) {
        throw { message: response.data.message };
      }

      this.updateLocalData(response.data.data, this.page_number);
    },
    // TODO::Permission  acls needs to be applied here
    async getInvoiceDataByDocId() {
      try {
        const data = {
          doc_id: this.docId,
        };

        await this.getDocumentById(this.docId);
        if (!this.record.doc_id) {
          throw { message: this.$t('INVALID_DOCUMENT') };
        }
        this.updateLocalData(this.record, this.doc_data_name);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    setImages() {
      const image_index = Number(this.page_number) - 1;
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(
          this.apiData[this.doc_data_name].images[image_index].path,
        );
      this.images = cleanUpImagesUrl(this.apiData[this.doc_data_name].images);
    },
    currentPage() {
      return this.page_number;
    },
    setImageDimensions() {
      const imageElm = $('#image_container') as HTMLElement;
      if (!imageElm) {
        return;
      }

      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
    },
    async imageclicked(id: string) {
      try {
        this.showLoading();
        this.image =
          this.baseUrl +
          '/' +
          cleanUpImagePath(this.apiData[this.doc_data_name].images[id].path);
        this.page_number = String(parseInt(id) + 1);

        if (!this.isPageNumberOcrDataExist(this.page_number)) {
          await this.getDocumentOcrData();
        }
        this.renderView();
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
        this.hideLoading();
      } finally {
      }
    },
    renderView() {
      this.setImageDimensions();
      this.setTokens();
    },
    windowResize() {
      setTimeout(() => {
        this.setImageDimensions();
      }, 0);
    },
    toggler() {
      this.windowResize();
    },
    setTokens() {
      if (!this.isPageNumberOcrDataExist(this.page_number)) {
        this.tokens = [];
        return;
      }
      this.tokens = this.apiData[this.page_number].tokens;
    },
  },
});
</script>

<style lang="scss" scoped>
.table-mode {
  background-color: $primary;
  font-weight: bold;
  padding: 0 4px 0 4px;
  margin-top: 6px;
}
</style>
