import { SessionStorage } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import {
  isObjectEmtpy,
  isUndefinedOrNull,
  isEmptyString,
} from 'src/utils/general';

export function getOcrSessionName(id: string) {
  return 'ocr_doc_' + id;
}

export function getDocDataName() {
  return 'doc_data';
}

export function addOcrDataInExistingSession(
  data: any,
  attr_name: string,
  doc_id: string,
) {
  try {
    const session_name = getOcrSessionName(doc_id);
    const saved_data = getOcrDataInSession(doc_id);

    if (saved_data == null || isObjectEmtpy(saved_data)) {
      createNew(data, attr_name, doc_id);
    }

    saved_data[attr_name] = data;
    SessionStorage.set(session_name, saved_data);
  } catch (err) {
    logError(err);
    return false;
  }
}

export function createNew(data: any, attr_name: string, doc_id: string) {
  const session_name = getOcrSessionName(doc_id);
  const new_data = newDataObject();
  new_data[attr_name] = data;
  SessionStorage.set(session_name, new_data);
}

function newDataObject() {
  return {} as dynamicObj;
}

export function removeOcrDataAndAddNew(data: any, doc_id: string) {
  const session_name = getOcrSessionName(doc_id);
  removeOcrData(session_name);
  SessionStorage.set(session_name, data);
}

export function removeOcrData(session_name: string) {
  SessionStorage.remove(session_name);
}

export function getOcrDataInSession(doc_id: string) {
  const session_name = getOcrSessionName(doc_id);
  return SessionStorage.has(session_name)
    ? (SessionStorage.getItem(session_name) as dynamicObj)
    : newDataObject();
}
