<template>
  <div
    class="image-decorator medi-selected-area-fields"
    ref="image-area"
    id="image_area"
    :style="{
      width: width + 'px',
    }"
  >
    <img
      @load="prepareImageData"
      id="screenshot2"
      class="original-image"
      style=""
      :src="url + '&reload=' + image_reload"
      alt="Original Image"
      v-if="url"
      :width="width"
    />
    <div
      class="select-areas--overlay"
      :style="{
        opacity: opacityOverlay,
        position: 'absolute',
        width: originImgSize.w + 'px',
        height: originImgSize.h + 'px',
        display: 'block',
      }"
    ></div>

    <template v-if="mode === 'debug_on'">
      <div v-for="item in areas" :key="item.id">
        <div>
          <div
            class="select-areas--outline outline"
            :style="{
              opacity: opacityOutline,
              position: 'absolute',
              cursor: 'default',
              width: item.width + 2 + 'px',
              height: item.height + 2 + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z,
              'font-size': item.font_size + 'px',
            }"
          ></div>
          <div
            class="select-areas--background_area"
            :style="{
              position: 'absolute',
              cursor: 'pointer',
              width: item.width + 3 + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
              'font-size': item.font_size + 'px',
            }"
          >
            {{ item.text
            }}<q-tooltip
              ><div v-for="(value, key) in item.fieldDef" :key="key">
                {{ key }} : {{ value }}<br /></div
            ></q-tooltip>
          </div>
        </div>
      </div>
    </template>
    <template v-else-if="mode === 'ocr'">
      <div v-for="item in areas" :key="item.id">
        <div class="text-black">
          <div
            class="select-areas--outline"
            :style="{
              opacity: opacityOutline,
              position: 'absolute',
              cursor: 'default',
              width: item.width + 2 + 'px',
              height: item.height + 2 + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z,
              'font-size': item.font_size + 'px',
            }"
          ></div>
          <div
            class="select-areas--background_area"
            :style="{
              position: 'absolute',
              cursor: 'pointer',
              width: item.width + 3 + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
              'font-size': item.font_size + 'px',
            }"
          >
            {{ item.text }}
          </div>
        </div>
      </div>
    </template>

    <div class="c-crop--hide_main">
      <img id="c-crop--hide_img" :src="url" alt="" :width="width" />
    </div>
  </div>
</template>
<script lang="ts">
import { debounce } from 'quasar';
import { defineComponent, ref } from 'vue';
import { $, type dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';

let _this: any;
let imageArea: HTMLElement;

export default defineComponent({
  mixins: [helperMixin],
  data() {
    return {
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      areas: [] as dynamicObj[],
      scrollLeft: 0,
      scrollTop: 0,
      imageHeight: 0,
      imageWidth: 0,
      image_reload: 1,
      item_loaded: false,
      opacityOverlay: 1,
    };
  },
  props: {
    cropUrl: {
      type: String,
      default:
        'https://dev.doc2api.cloudintegration.eu/resource/image/1b90b6d5-63b5-446b-92a4-a60d57dc0edd/1.png',
    },
    width: {
      type: Number,
      default: 1500,
    },
    height: {
      type: Number,
      default: 1500,
    },
    opacityOutline: {
      type: Number,
      default: 0.2,
    },
    posCorrection: {
      type: Boolean,
      default: false,
    },
    tableAreas: {
      type: [Array, Object] as any,
      default: () => [],
    },
    isReadOnly: {
      type: Boolean,
      default: true,
    },
    mode: {
      type: String,
      default: 'ocr',
    },
    token_len: {
      type: Number,
      default: 0,
    },
  },
  components: {},
  watch: {
    async cropUrl(val) {
      this.url = val;
      this.image_reload++;
      await this.setSize();
    },
    async width(val) {
      await this.setSize();
      this.image_reload++;
    },
    tableAreas: {
      handler() {
        if (this.imageWidth && this.imageHeight) {
          this.prepareDataForAreas();
        }
      },
      deep: true,
    },
    mode(val) {
      if (val === 'doc') {
        this.opacityOverlay = 0;
      } else {
        this.opacityOverlay = 1;
      }
    },
  },
  setup() {
    return {
      is_debug: ref(true),
    };
  },
  updated: debounce(() => {
    _this.$nextTick(function () {
      let tokenEls = document.querySelectorAll<HTMLElement>(
        '.select-areas--outline',
      );
      if (tokenEls.length === _this.token_len && _this.item_loaded == true) {
        _this.hideLoading();
        _this.item_loaded = false;
      }
    });
  }, 500),
  methods: {
    isDebugFlagHandler() {
      this.is_debug = false;
      if (this.$route.query && this.$route.query.is_debug === 'true') {
        this.is_debug = true;
      }
    },
    areaDisplayPosX(area: any): any {
      return area.x + (this.posCorrection ? this.posImg.left : 0);
    },
    areaDisplayPosY(area: any): any {
      return area.y + (this.posCorrection ? this.posImg.top : 0);
    },
    mousePosX(e: any) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e: any) {
      return e.pageY - this.posImg.top;
    },
    async setSize() {
      if (!this.url) {
        return;
      }
      let imgSize: any = await this.getSize(this.url);
      this.originImgSize = imgSize;
    },
    // Get the size of the src image
    getSize(src: any) {
      let img = this.$el.querySelector('#c-crop--hide_img') as HTMLImageElement;
      return new Promise((resolve) => {
        if (src && img) {
          const done = () => resolve(_this.getSizeImg(img));
          img.onload = done;
          img.onerror = () => resolve({ w: 0, h: 0, r: 0 });
          if (img.src === src && img.complete && img.naturalWidth > 0) {
            done();
          } else {
            img.src = src;
          }
        } else {
          resolve({
            w: 0,
            h: 0,
            r: 0,
          });
        }
      });
    },
    getSizeImg(img: any) {
      let w = img.width;
      let h = img.height;
      let r = w === 0 && h === 0 ? 0 : w / h;
      return {
        w: w,
        h: h,
        r: r,
      };
    },
    calcPosOfBox() {
      // set posImg static
      let imageAreaRef: any = this.$refs['image-area'];

      this.scrollLeft =
        window.pageXOffset || document.documentElement.scrollLeft;
      this.scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      let imageAreaTop = imageAreaRef.getBoundingClientRect().top;
      let imageAreaLeft = imageAreaRef.getBoundingClientRect().left;

      this.posImg.top = imageAreaTop + this.scrollTop;

      this.posImg.left = imageAreaLeft + this.scrollLeft;
      // logInfo(this.posImg.top,this.posImg.left,'calcPosOfBox' );
    },

    // this function only creats a test overlay reactangle. just to understand what data is expexted to creat corret overlay
    creatReactangle(
      x: number,
      y: number,
      width: number,
      height: number,
      fieldDef: any,
      key: string,
    ) {
      let newAreaId = null;
      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }
      if (newAreaId) {
        let font_size = 14;
        if (fieldDef.hasOwnProperty('font_size')) {
          font_size = Math.floor(this.imageWidth * fieldDef.font_size);
        }
        let newArea = {
          id: newAreaId,
          x: x,
          y: y,
          width: width,
          height: height,
          z: 0,
          resizable: false,
          fieldDef: fieldDef,
          text: fieldDef.text,
          font_size: font_size,
          key: key,
        };

        this.areas.push(newArea);
      }
    },
    prepareImageData() {
      let screenshot2 = $('#screenshot2') as HTMLElement;
      if (screenshot2) {
        this.imageWidth = screenshot2.offsetWidth;
        this.imageHeight = screenshot2.offsetHeight;
        this.prepareDataForAreas();
      }
    },
    prepareDataForAreas() {
      try {
        this.item_loaded = true;
        this.showLoading();
        this.areas = [] as dynamicObj[];
        if (!this.tableAreas) {
          return;
        }
        for (const key in this.tableAreas) {
          let field = this.tableAreas[key];
          let startX = Math.floor(this.imageWidth * field.normalizedX0);
          let startY = Math.floor(this.imageHeight * field.normalizedY0);
          let endX = Math.floor(this.imageWidth * field.normalizedX1);
          let endY = Math.floor(this.imageHeight * field.normalizedY1);

          let width = endX - startX;
          let height = endY - startY;

          this.creatReactangle(startX, startY, width, height, field, key);
        }
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  mounted() {
    _this = this;
    this.setSize();
    imageArea = $('#image_area') as HTMLElement;
    imageArea.addEventListener('scroll', this.calcPosOfBox);
    this.calcPosOfBox();
  },
  unmounted: function () {
    imageArea.removeEventListener('scroll', this.calcPosOfBox);
  },
});
</script>
