  }

  &--outline {
    //  background: #fff url(data:image/gif;base64,);
    overflow: hidden;
  }
}

.outline {
  outline: 1px solid #e50202;
}

.delete-area {
  position: absolute;
  cursor: pointer;
  padding: 5px;
}
</style>
